  2879      memset(&aux, 0, sizeof(ks_tokaux_t));
  2880      for (p = kstrtok(s->s, "\t", &aux), i = 0; p; p = kstrtok(0, 0, &aux), ++i) {
  2881          q = (char*)aux.p;
