  1382  cram_codec *cram_xpack_decode_init(cram_block_compression_hdr *hdr,
  1383                                     char *data, int size,
  1384                                     enum cram_encoding codec,
  1385                                     enum cram_external_type option,
  1386                                     int version, varint_vec *vv) {
  1387      cram_codec *c;
  1388      char *cp = data;
  1389      char *endp = data+size;
  1390
  1391      if (!(c = malloc(sizeof(*c))))
  1392          return NULL;
  1393
  1394      c->codec  = E_XPACK;
  1395      if (option == E_LONG)
  1396          c->decode = cram_xpack_decode_long;
  1397      else if (option == E_INT)
  1398          c->decode = cram_xpack_decode_int;
  1399      else if (option == E_BYTE_ARRAY || option == E_BYTE)
  1400          c->decode = cram_xpack_decode_char;
  1401      else {
  1402          fprintf(stderr, "BYTE_ARRAYs not supported by this codec\n");
  1403          return NULL;
  1404      }
  1405      c->free = cram_xpack_decode_free;
  1406      c->size = cram_xpack_decode_size;
  1407      c->get_block = cram_xpack_get_block;
  1408
  1409      c->u.xpack.nbits = vv->varint_get32(&cp, endp, NULL);
  1410      c->u.xpack.nval  = vv->varint_get32(&cp, endp, NULL);
  1411      int i;
  1412      for (i = 0; i < c->u.xpack.nval; i++) {
  1413          uint32_t v = vv->varint_get32(&cp, endp, NULL);
  1414          if (v >= 256) return NULL;
  1415          c->u.xpack.rmap[i] = v; // reverse map: e.g 0-3 to P,A,C,K
  1416      }
  1417
  1418      int encoding = vv->varint_get32(&cp, endp, NULL);
  1419      int sub_size = vv->varint_get32(&cp, endp, NULL);
  1420      if (sub_size < 0 || endp - cp < sub_size)
  1421          goto malformed;
  1422      c->u.xpack.sub_codec = cram_decoder_init(hdr, encoding, cp, sub_size,
  1423                                               option, version, vv);
  1424      if (c->u.xpack.sub_codec == NULL)
  1425          goto malformed;
  1426      cp += sub_size;
  1427
  1428      if (cp - data != size
  1429          || c->u.xpack.nbits < 0 || c->u.xpack.nbits > 8 * sizeof(int64_t)) {
  1430      malformed:
  1431          fprintf(stderr, "Malformed xpack header stream\n");
  1432          free(c);
  1433          return NULL;
  1434      }
  1435
  1436      return c;
  1437  }
